import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static void bitAdd(long[] t, int i, long x) {
        int n = t.length - 1;
        for (; i <= n; i += i & -i) t[i] += x;
    }

    static long bitSum(long[] t, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] par = new long[(int) n];
        for (int i = 0; i < par.length; i++) par[i] = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] ops = new long[(int) q][3];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = Long.parseLong(next());
            }
        }

        int cn = (int) n;
        long[] sz = new long[cn + 1];
        long[] tin = new long[cn + 1];
        long[] nxt = new long[cn + 1];
        long[] init = new long[cn + 1];
        java.util.Arrays.fill(sz, 1);
        for (int v = cn; v >= 2; v--) sz[(int) par[v - 1]] += sz[v];
        nxt[1] = 1;
        init[1] = a[0];
        for (int v = 2; v <= cn; v++) {
            int p = (int) par[v - 1];
            tin[v] = nxt[p];
            nxt[p] += sz[v];
            nxt[v] = tin[v] + 1;
            init[v] = init[p] + a[v - 1];
        }
        long[] t = new long[cn + 2];
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            long kind = ops[k][0];
            int v = (int) ops[k][1];
            long x = ops[k][2];
            if (kind == 1) {
                bitAdd(t, (int) tin[v] + 1, x);
                bitAdd(t, (int) (tin[v] + sz[v]) + 1, -x);
            } else {
                if (out.length() > 0) out.append(" ");
                out.append(init[v] + bitSum(t, (int) tin[v] + 1));
            }
        }
        System.out.println(out);
    }
}
